        return f"{expr_display(e.left)} {OP_DISPLAY[e.op]} {expr_display(e.right)}"
    if isinstance(e, GroupExpr):
        return expr_display(e.inner)
    if isinstance(e, NegExpr):
        return "-" + expr_display(e.inner)
