# ---------------- roots ----------------
class Root:
    def __init__(self, path):
        self.path = path
        self.mindepth = None
        self.maxdepth = None
        self.archives = False
        self.symlinks = False
        self.gitignore = False
        self.hgignore = False
        self.dockerignore = False
        self.dfs = False
        self.regexp = False
        self.alias = None

def expand_tilde(p):
    home = os.environ.get('HOME') or os.path.expanduser('~')
    if p == '~':
        return home
    if p.startswith('~/'):
        return home + p[1:]
    return p

ROOT_FLAG_OPTS = {
    'archives':'archives','arc':'archives',
    'symlinks':'symlinks','sym':'symlinks',
    'gitignore':'gitignore','git':'gitignore',
    'nogitignore':'nogitignore','nogit':'nogitignore',
    'hgignore':'hgignore','hg':'hgignore',
    'nohgignore':'nohgignore','nohg':'nohgignore',
    'dockerignore':'dockerignore','docker':'dockerignore','dock':'dockerignore',
    'nodockerignore':'nodockerignore','nodocker':'nodockerignore','nodock':'nodockerignore',
    'dfs':'dfs','bfs':'bfs','regexp':'regexp',
}

def parse_roots(tokens, config):
    # split by commas at depth 0
    chunks = []
    cur = []
    depth = 0
    stack = []
    for t in tokens:
        if t.kind == 'LPAREN':
            stack.append(t.open_type); depth += 1
        elif t.kind == 'RPAREN':
            if stack: stack.pop()
            depth = max(0, depth-1)
        if t.kind == 'COMMA' and depth == 0:
            chunks.append(cur); cur = []
        else:
            cur.append(t)
    chunks.append(cur)
    roots = []
    for chunk in chunks:
        if not chunk:
            continue
        # first token is path
        path_tok = chunk[0]
        root = Root(expand_tilde(path_tok.text))
        root.gitignore = config.gitignore
        root.hgignore = config.hgignore
        root.dockerignore = config.dockerignore
        i = 1
        while i < len(chunk):
            t = chunk[i]
            if t.kind not in ('WORD','STRING'):
                raise ParseError("could not parse tokens at the end of the query")
            low = t.text.lower()
            if low in ('mindepth','maxdepth','depth'):
                if i+1 >= len(chunk):
                    raise ParseError("Error parsing root options")
                vtok = chunk[i+1]
                if not re.fullmatch(r'\d+', vtok.text):
                    raise ParseError("could not parse tokens at the end of the query")
                v = int(vtok.text)
                if low == 'mindepth':
                    root.mindepth = v
                else:
                    root.maxdepth = v
                i += 2; continue
            if low == 'as':
                if i+1 >= len(chunk):
                    raise ParseError("Error parsing root options")
                root.alias = chunk[i+1].text
                i += 2; continue
            if low in ROOT_FLAG_OPTS:
                attr = ROOT_FLAG_OPTS[low]
                if attr == 'archives': root.archives = True
                elif attr == 'symlinks': root.symlinks = True
                elif attr == 'gitignore': root.gitignore = True
                elif attr == 'nogitignore': root.gitignore = False
                elif attr == 'hgignore': root.hgignore = True
                elif attr == 'nohgignore': root.hgignore = False
                elif attr == 'dockerignore': root.dockerignore = True
                elif attr == 'nodockerignore': root.dockerignore = False
                elif attr == 'dfs': root.dfs = True
                elif attr == 'bfs': root.dfs = False
                elif attr == 'regexp': root.regexp = True
                i += 1; continue
            raise ParseError("could not parse tokens at the end of the query")
        roots.append(root)
    if not roots:
        r = Root('.')
        r.gitignore = config.gitignore; r.hgignore = config.hgignore; r.dockerignore = config.dockerignore
        roots = [r]
    return roots

