    segments = {'fields':[], 'roots':[], 'where':[], 'group':[], 'order':[], 'limit':[], 'offset':[], 'into':[]}
    present = set()
    current = 'fields'
    depth_stack = []
    i = 0
    first = True
    while i < len(tokens):
        t = tokens[i]
        if t.kind == 'LPAREN':
            depth_stack.append(t.open_type)
            segments[current].append(t); i += 1; continue
        if t.kind == 'RPAREN':
            if depth_stack: depth_stack.pop()
            segments[current].append(t); i += 1; continue
        if len(depth_stack) == 0 and t.kind == 'WORD':
            low = t.text.lower()
            # skip leading SELECT
            if current == 'fields' and not segments['fields'] and low == 'select' and 'fields' not in present:
                i += 1; continue
