            nxt_low = nxt.text.lower() if nxt is not None and nxt.kind in ('WORD','STRING') else None
            if low in CLAUSE_WORDS:
                current = {'from':'roots','where':'where','limit':'limit','offset':'offset','into':'into'}[low]
                present.add(current); i += 1; continue
            if low == 'group' and (nxt_low == 'by' or current != 'fields'):
                current = 'group'; present.add(current); i += 1
                if nxt_low == 'by': i += 1
                continue
            if low == 'order' and (nxt_low == 'by' or current != 'fields'):
                current = 'order'; present.add(current); i += 1
                if nxt_low == 'by': i += 1
                continue
