def parse_columns_segment(tokens, alias_ctx, allow_star=True):
    parser = ExprParser(tokens, alias_ctx)
    cols = []
    while not parser.at_end():
        t = parser.peek()
        if t.kind == 'COMMA':
            parser.next(); continue
        if t.kind == 'RPAREN':
            raise ParseError("could not parse tokens at the end of the query")
        e = parser.parse_expr()
        cols.append(e)
