# ---------------- file records ----------------
def _statx_btime(path, follow):
    try:
        import ctypes
        libc = ctypes.CDLL(None, use_errno=True)
        buf = ctypes.create_string_buffer(256)
        path_b = os.fsencode(path)
        AT_FDCWD = -100
        AT_SYMLINK_NOFOLLOW = 0x100
        flags = 0 if follow else AT_SYMLINK_NOFOLLOW
        STATX_BASIC = 0x07ff
        # syscall number for statx on x86_64 / aarch64 is 332 / 291; try x86_64 then aarch64
        res = -1
        for nr in (332, 291):
            res = libc.syscall(nr, AT_FDCWD, path_b, flags, STATX_BASIC, buf)
            if res == 0:
                break
        if res != 0:
            return None
        mask = struct.unpack_from('<I', buf.raw, 0)[0]
        if not (mask & 0x800):
            return None
        sec = struct.unpack_from('<q', buf.raw, 80)[0]
        if sec == 0:
            return None
        return sec
    except Exception:
        return None

