def parse_image_dimensions(rec):
    if rec._dims_done:
        return rec._dims
    rec._dims_done = True
    rec._dims = (None, None)
    if rec.archive is not None:
        return rec._dims
    name = rec.name()
    _, ext = split_filename(name)
    ext = ext.lower()
    data = None
    # read up to 256k for header parsing (svg may need text)
    try:
        if not os.path.isfile(rec.fs_path):
            return rec._dims
        with open(rec.fs_path, 'rb') as f:
            data = f.read(262144)
    except Exception:
        return rec._dims
    if data is None:
        return rec._dims
    try:
        if ext == 'mp4' or ext == 'mov' or ext == 'm4v':
            wh = _mp4_dims(data, rec.fs_path)
            rec._dims = wh; return wh
        if data.startswith(b'\x89PNG\r\n\x1a\n') and len(data) >= 24:
            w, h = struct.unpack('>II', data[16:24]); rec._dims = (w,h); return rec._dims
        if data[:6] in (b'GIF87a', b'GIF89a') and len(data) >= 10:
            w, h = struct.unpack('<HH', data[6:10]); rec._dims = (w,h); return rec._dims
        if data.startswith(b'BM') and len(data) >= 26:
            dib = struct.unpack('<I', data[14:18])[0]
            if dib >= 40:
                w, h = struct.unpack('<ii', data[18:26]); rec._dims = (abs(w), abs(h)); return rec._dims
            else:
                w, h = struct.unpack('<HH', data[18:22]); rec._dims = (w,h); return rec._dims
        if data.startswith(b'\xff\xd8'):
            wh = _jpeg_dims(data)
            if wh: rec._dims = wh; return wh
        if data.startswith(b'RIFF') and data[8:12] == b'WEBP':
            wh = _webp_dims(data)
            if wh: rec._dims = wh; return wh
        if data[:4] in (b'II*\x00', b'MM\x00*'):
            wh = _tiff_dims(data)
            if wh: rec._dims = wh; return wh
        if data.startswith(b'8BPS') and len(data) >= 22:
            h, w = struct.unpack('>II', data[14:22]); rec._dims = (w,h); return rec._dims
