                if mv:
                    parts = mv.group(1).split()
                    if len(parts) == 4:
                        rec._dims = (int(float(parts[2])), int(float(parts[3]))); return rec._dims
    except Exception:
        return rec._dims
    return rec._dims

def _jpeg_dims(data):
    i = 2
    while i+9 < len(data):
        if data[i] != 0xFF:
            i += 1; continue
        marker = data[i+1]
        if marker in (0xD8, 0x01) or 0xD0 <= marker <= 0xD9:
            i += 2; continue
        if i+4 > len(data): break
        length = struct.unpack('>H', data[i+2:i+4])[0]
        if marker in (0xC0,0xC1,0xC2,0xC3,0xC5,0xC6,0xC7,0xC9,0xCA,0xCB,0xCD,0xCE,0xCF):
            if i+9 <= len(data):
                h, w = struct.unpack('>HH', data[i+5:i+9]); return (w,h)
            break
        i += 2 + length
    return None

def _webp_dims(data):
    # chunk after RIFF header
    if len(data) < 30: return None
    typ = data[12:16]
    if typ == b'VP8X' and len(data) >= 30:
        w = int.from_bytes(data[24:27],'little')+1; h = int.from_bytes(data[27:30],'little')+1; return (w,h)
    if typ == b'VP8 ' and len(data) >= 30:
        # frame tag 3, start code 3, scaling 2, then 14-bit dims
        off = 20+8
        if len(data) >= off+4:
            v = struct.unpack('<I', data[off:off+4])[0]
            w = v & 0x3fff; h = (v>>16) & 0x3fff; return (w,h)
    if typ == b'VP8L' and len(data) >= 25:
        v = struct.unpack('<I', data[21:25])[0]
        w = (v & 0x3fff)+1; h = ((v>>14)&0x3fff)+1; return (w,h)
    return None

def _tiff_dims(data):
    endian = '<' if data[:2]==b'II' else '>'
    if len(data) < 8: return None
    off = struct.unpack(endian+'I', data[4:8])[0]
    if off+2 > len(data): return None
    count = struct.unpack(endian+'H', data[off:off+2])[0]
    w=h=None
    for k in range(count):
        e = off+2+k*12
        if e+12 > len(data): break
        tag, typ, num = struct.unpack(endian+'HHI', data[e:e+8])
        valoff = e+8
        if typ == 3:
            val = struct.unpack(endian+'H', data[valoff:valoff+2])[0]
        elif typ == 4:
            val = struct.unpack(endian+'I', data[valoff:valoff+4])[0]
        else:
            continue
        if tag == 256: w=val
        if tag == 257: h=val
    return (w,h) if w is not None or h is not None else None

def _mp4_dims(data, path):
    # search tkhd boxes in (possibly larger) file
    blob = data
    try:
        if len(blob) < 200000:
            with open(path,'rb') as f: blob = f.read(2000000)
    except Exception:
        pass
    idx = blob.find(b'tkhd')
    if idx == -1: return (None,None)
    size = struct.unpack('>I', blob[idx-4:idx])[0] if idx>=4 else 0
    if size >= 16 and idx-4+size <= len(blob)+size:
        end = idx-4+size
        if end-8 >= idx:
            w = struct.unpack('>I', blob[end-8:end-4])[0] >> 16
            h = struct.unpack('>I', blob[end-4:end])[0] >> 16
            if w or h: return (w,h)
    return (None,None)

