EXIF_TAG_MAP = {}  # filled below as canonical -> (tag, ifd)
def parse_exif(rec):
    if rec._exif_done:
        return rec._exif
    rec._exif_done = True
    rec._exif = {}
    if rec.archive is not None:
        return rec._exif
