        if not os.path.isfile(rec.fs_path):
            return rec._exif
        with open(rec.fs_path,'rb') as f:
            data = f.read(1048576)
    except Exception:
        return rec._exif
    tiff = None
    if data[:2] in (b'II', b'MM'):
        tiff = data
    elif data[:2] == b'\xff\xd8':
