def _tiff_values(data, endian, typ, count, val_bytes, val_offset):
    sizes = {1:1,2:1,3:2,4:4,5:8,7:1,9:4,10:8,6:1,8:2,11:4,12:8}
    sz = sizes.get(typ,1)
    total = sz*count
    if total <= 4:
        raw = val_bytes[:total]
    else:
        off = val_offset
        if off+total > len(data): return None
        raw = data[off:off+total]
    if typ == 2:
        return raw.decode('utf-8','replace').rstrip('\x00')
    if typ == 7:
        return raw
    vals=[]
    for k in range(count):
        chunk = raw[k*sz:(k+1)*sz]
        if len(chunk) < sz: break
        if typ == 3: vals.append(struct.unpack(endian+'H', chunk)[0])
        elif typ == 4: vals.append(struct.unpack(endian+'I', chunk)[0])
        elif typ in (1,6): vals.append(chunk[0])
        elif typ == 8: vals.append(struct.unpack(endian+'h', chunk)[0])
        elif typ == 9: vals.append(struct.unpack(endian+'i', chunk)[0])
        elif typ == 5:
            n,d = struct.unpack(endian+'II', chunk); vals.append((n,d))
        elif typ == 10:
            n,d = struct.unpack(endian+'ii', chunk); vals.append((n,d))
        elif typ == 11: vals.append(struct.unpack(endian+'f', chunk)[0])
        elif typ == 12: vals.append(struct.unpack(endian+'d', chunk)[0])
        else: vals.append(chunk)
    if count == 1:
