    return vals

def _read_ifd(data, endian, off, out, prefix=''):
    if off+2 > len(data): return
    count = struct.unpack(endian+'H', data[off:off+2])[0]
    for k in range(count):
        e = off+2+k*12
        if e+12 > len(data): break
        tag, typ, num = struct.unpack(endian+'HHI', data[e:e+8])
        val_bytes = data[e+8:e+12]
        val_off = struct.unpack(endian+'I', val_bytes)[0] if typ not in (1,2,3,6,7,8) or ( {1:1,2:1,3:2,4:4,5:8,7:1,9:4,10:8,6:1,8:2}.get(typ,1)*num > 4) else e+8
        # compute actual offset for large values
        sizes = {1:1,2:1,3:2,4:4,5:8,7:1,9:4,10:8,6:1,8:2,11:4,12:8}
        if sizes.get(typ,1)*num > 4:
            val_off = struct.unpack(endian+'I', val_bytes)[0]
        v = _tiff_values(data, endian, typ, num, val_bytes, val_off)
        out[(prefix, tag)] = v
        if tag == 0x8769 and isinstance(v,int):
            _read_ifd(data, endian, v, out, 'exif')
        if tag == 0x8825 and isinstance(v,int):
            _read_ifd(data, endian, v, out, 'gps')
    # next ifd ignored

def _parse_tiff_exif(data):
    if len(data)<8: return {}
    endian = '<' if data[:2]==b'II' else '>'
    off = struct.unpack(endian+'I', data[4:8])[0]
    raw = {}
    _read_ifd(data, endian, off, raw, '')
    # flatten: exif/gps override / merge
    flat = {}
    for (prefix,tag),v in raw.items():
        flat[tag]=v
        flat[(prefix,tag)]=v
    return flat

def _rational_float(v):
    if isinstance(v, tuple):
        n,d = v; return n/d if d else 0.0
    if isinstance(v,(int,float)): return float(v)
    return None

def _exif_format_value(rec, canonical):
    exif = parse_exif(rec)
    if not exif:
        return ""
    def get(tag, prefix=None):
        if prefix is not None and (prefix,tag) in exif: return exif[(prefix,tag)]
        return exif.get(tag)
    def as_str(v):
        if v is None: return ""
        if isinstance(v, bytes): return v.decode('utf-8','replace').rstrip('\x00')
        if isinstance(v, list): return ", ".join(str(_rational_float(x) if isinstance(x,tuple) else x) for x in v)
        if isinstance(v, tuple):
            f=_rational_float(v); return rust_float_str(f) if f is not None else ""
        return str(v)
    mapping = {
        'exif_datetime': (0x0132,''), 'exif_datetime_original': (0x9003,'exif'),
        'exif_make': (0x010F,''), 'exif_model': (0x0110,''), 'exif_software': (0x0131,''),
        'exif_artist': (0x013B,''), 'exif_copyright': (0x8298,''), 'exif_description': (0x010E,''),
    }
    if canonical in mapping:
        tag,prefix = mapping[canonical]
        v = get(tag, prefix if prefix else None)
        if v is None and prefix: v=get(tag)
        return as_str(v).strip() if isinstance(v,str) else as_str(v)
    if canonical == 'exif_version':
        v=get(0x9000,'exif');
        if isinstance(v,bytes): return v.decode('ascii','replace').rstrip('\x00')
        return as_str(v)
    if canonical == 'exif_user_comment':
        v=get(0x9286,'exif')
        if isinstance(v,bytes):
            b=v
            if b.startswith(b'ASCII\x00\x00\x00'): b=b[8:]
            elif b.startswith(b'JIS\x00\x00\x00\x00\x00'): b=b[8:]
            elif b.startswith(b'UNICODE\x00'): b=b[8:]
            return b.decode('utf-8','replace').rstrip('\x00').strip()
        return as_str(v)
    if canonical in ('exif_image_width','exif_image_height'):
        tag = 0xA002 if canonical=='exif_image_width' else 0xA003
        v=get(tag,'exif')
        if v is None: v=get(0x0100 if canonical=='exif_image_width' else 0x0101)
        return as_str(v)
    if canonical in ('exif_altitude','exif_latitude','exif_longitude'):
        # GPS
        if canonical=='exif_altitude':
            v=get(6,'gps'); f=_rational_float(v) if not isinstance(v,list) else None
            if isinstance(v,list) and v: f=_rational_float(v[0])
            if f is None: return ""
            ref=get(5,'gps')
            if ref==1: f=-f
            return rust_float_str(f)
        tag = 2 if canonical=='exif_latitude' else 4
        ref_tag = 1 if canonical=='exif_latitude' else 3
        v=get(tag,'gps'); ref=get(ref_tag,'gps')
        if isinstance(v,list) and len(v)>=3:
            d=_rational_float(v[0]) or 0; mi=_rational_float(v[1]) or 0; s=_rational_float(v[2]) or 0
            dec=d+mi/60+s/3600
            if ref in ('S','W', b'S', b'W'): dec=-dec
            return rust_float_str(dec)
        return ""
    # numeric / rational tags
    tagmap = {
        'exif_exposure_time':0x829A,'exif_aperture':0x9202,'exif_shutter_speed':0x9201,'exif_f_number':0x829D,
        'exif_iso_speed':0x8833,'exif_sensitivity':0x8833,'exif_focal_length':0x920A,'exif_max_aperture':0x9205,
        'exif_digital_zoom':0xA404,'exif_exposure_bias':0x9204,
    }
    if canonical in tagmap:
        v=get(tagmap[canonical],'exif')
        if isinstance(v,list): v=v[0] if v else None
        if isinstance(v,tuple):
            f=_rational_float(v); return rust_float_str(f) if f is not None else ""
        return as_str(v)
    simple = {
        'exif_lens_make':0xA433,'exif_lens_model':0xA434,'exif_lens_serial':0xA435,'exif_body_serial':0xA431,
        'exif_orientation':0x0112,'exif_flash':0x9209,'exif_color_space':0xA001,'exif_exposure_program':0x8822,
        'exif_white_balance':0xA403,'exif_metering_mode':0x9207,'exif_scene_type':0xA301,'exif_contrast':0xA408,
        'exif_saturation':0xA409,'exif_sharpness':0xA40A,
    }
    if canonical in simple:
        v=get(simple[canonical],'exif')
        if v is None: v=get(simple[canonical])
        return as_str(v)
    return ""

