# ---------------- image size / mp3 / exif ----------------
def parse_image_dimensions(rec):
    if rec._dims_done:
        return rec._dims
    rec._dims_done = True
    rec._dims = (None, None)
    if rec.archive is not None:
        return rec._dims
    name = rec.name()
    _, ext = split_filename(name)
    ext = ext.lower()
    data = None
    # read up to 256k for header parsing (svg may need text)
    try:
        if not os.path.isfile(rec.fs_path):
            return rec._dims
        with open(rec.fs_path, 'rb') as f:
            data = f.read(262144)
    except Exception:
        return rec._dims
    if data is None:
        return rec._dims
    try:
        if ext == 'mp4' or ext == 'mov' or ext == 'm4v':
            wh = _mp4_dims(data, rec.fs_path)
            rec._dims = wh; return wh
        if data.startswith(b'\x89PNG\r\n\x1a\n') and len(data) >= 24:
            w, h = struct.unpack('>II', data[16:24]); rec._dims = (w,h); return rec._dims
        if data[:6] in (b'GIF87a', b'GIF89a') and len(data) >= 10:
            w, h = struct.unpack('<HH', data[6:10]); rec._dims = (w,h); return rec._dims
        if data.startswith(b'BM') and len(data) >= 26:
            dib = struct.unpack('<I', data[14:18])[0]
            if dib >= 40:
                w, h = struct.unpack('<ii', data[18:26]); rec._dims = (abs(w), abs(h)); return rec._dims
            else:
                w, h = struct.unpack('<HH', data[18:22]); rec._dims = (w,h); return rec._dims
        if data.startswith(b'\xff\xd8'):
            wh = _jpeg_dims(data)
            if wh: rec._dims = wh; return wh
        if data.startswith(b'RIFF') and data[8:12] == b'WEBP':
            wh = _webp_dims(data)
            if wh: rec._dims = wh; return wh
        if data[:4] in (b'II*\x00', b'MM\x00*'):
            wh = _tiff_dims(data)
            if wh: rec._dims = wh; return wh
        if data.startswith(b'8BPS') and len(data) >= 22:
            h, w = struct.unpack('>II', data[14:22]); rec._dims = (w,h); return rec._dims
        if ext == 'svg' or data.lstrip()[:4] == b'<svg' or b'<svg' in data[:1024]:
            txt = data.decode('utf-8','ignore')
            m = re.search(r'<svg[^>]*>', txt)
            if m:
                tag = m.group(0)
                mw = re.search(r'width\s*=\s*"([\d.]+)', tag); mh = re.search(r'height\s*=\s*"([\d.]+)', tag)
                if mw and mh:
                    rec._dims = (int(float(mw.group(1))), int(float(mh.group(1)))); return rec._dims
                mv = re.search(r'viewBox\s*=\s*"([\d.\s-]+)"', tag)
                if mv:
                    parts = mv.group(1).split()
                    if len(parts) == 4:
                        rec._dims = (int(float(parts[2])), int(float(parts[3]))); return rec._dims
    except Exception:
        return rec._dims
    return rec._dims

def _jpeg_dims(data):
    i = 2
    while i+9 < len(data):
        if data[i] != 0xFF:
            i += 1; continue
        marker = data[i+1]
        if marker in (0xD8, 0x01) or 0xD0 <= marker <= 0xD9:
            i += 2; continue
        if i+4 > len(data): break
        length = struct.unpack('>H', data[i+2:i+4])[0]
        if marker in (0xC0,0xC1,0xC2,0xC3,0xC5,0xC6,0xC7,0xC9,0xCA,0xCB,0xCD,0xCE,0xCF):
            if i+9 <= len(data):
                h, w = struct.unpack('>HH', data[i+5:i+9]); return (w,h)
            break
        i += 2 + length
    return None

def _webp_dims(data):
    # chunk after RIFF header
    if len(data) < 30: return None
    typ = data[12:16]
    if typ == b'VP8X' and len(data) >= 30:
        w = int.from_bytes(data[24:27],'little')+1; h = int.from_bytes(data[27:30],'little')+1; return (w,h)
    if typ == b'VP8 ' and len(data) >= 30:
        # frame tag 3, start code 3, scaling 2, then 14-bit dims
        off = 20+8
        if len(data) >= off+4:
            v = struct.unpack('<I', data[off:off+4])[0]
            w = v & 0x3fff; h = (v>>16) & 0x3fff; return (w,h)
    if typ == b'VP8L' and len(data) >= 25:
        v = struct.unpack('<I', data[21:25])[0]
        w = (v & 0x3fff)+1; h = ((v>>14)&0x3fff)+1; return (w,h)
    return None

def _tiff_dims(data):
    endian = '<' if data[:2]==b'II' else '>'
    if len(data) < 8: return None
    off = struct.unpack(endian+'I', data[4:8])[0]
    if off+2 > len(data): return None
    count = struct.unpack(endian+'H', data[off:off+2])[0]
    w=h=None
    for k in range(count):
        e = off+2+k*12
        if e+12 > len(data): break
        tag, typ, num = struct.unpack(endian+'HHI', data[e:e+8])
        valoff = e+8
        if typ == 3:
            val = struct.unpack(endian+'H', data[valoff:valoff+2])[0]
        elif typ == 4:
            val = struct.unpack(endian+'I', data[valoff:valoff+4])[0]
        else:
            continue
        if tag == 256: w=val
        if tag == 257: h=val
    return (w,h) if w is not None or h is not None else None

def _mp4_dims(data, path):
    # search tkhd boxes in (possibly larger) file
    blob = data
    try:
        if len(blob) < 200000:
            with open(path,'rb') as f: blob = f.read(2000000)
    except Exception:
        pass
    idx = blob.find(b'tkhd')
    if idx == -1: return (None,None)
    size = struct.unpack('>I', blob[idx-4:idx])[0] if idx>=4 else 0
    if size >= 16 and idx-4+size <= len(blob)+size:
        end = idx-4+size
        if end-8 >= idx:
            w = struct.unpack('>I', blob[end-8:end-4])[0] >> 16
            h = struct.unpack('>I', blob[end-4:end])[0] >> 16
            if w or h: return (w,h)
    return (None,None)

