        if version_bits==1 or layer_bits==0 or br_idx in (0,15) or sr_idx==3:
            pos += 1; continue
        if version_bits==3:
            bitrate = MP3_BITRATES_V1_L3[br_idx]; freq = MP3_FREQS[3][sr_idx]; samples=1152
            frame_len = int(144*bitrate*1000/freq)+padding if freq else 0
        else:
            bitrate = MP3_BITRATES_V2_L3[br_idx]; freq = MP3_FREQS.get(version_bits,[22050,24000,16000])[sr_idx]; samples=576
            frame_len = int(72*bitrate*1000/freq)+padding if freq else 0
        if first_bitrate is None:
            first_bitrate=bitrate; sample_rate=freq
        if frame_len <= 4:
            break
        total_samples += samples; frames+=1
        # only use frame length if plausible, else advance
        pos += frame_len
        if frames > 200000:
            break
    if sample_rate and frames:
        info['freq']=sample_rate; info['bitrate']=first_bitrate; info['duration']= total_samples//sample_rate if sample_rate else None
    return info

