def _tiff_values(data, endian, typ, count, val_bytes, val_offset):
    sizes = {1:1,2:1,3:2,4:4,5:8,7:1,9:4,10:8,6:1,8:2,11:4,12:8}
    sz = sizes.get(typ,1)
