    if typ == 7:
        return raw
    vals=[]
    for k in range(count):
        chunk = raw[k*sz:(k+1)*sz]
        if len(chunk) < sz: break
        if typ == 3: vals.append(struct.unpack(endian+'H', chunk)[0])
        elif typ == 4: vals.append(struct.unpack(endian+'I', chunk)[0])
        elif typ in (1,6): vals.append(chunk[0])
        elif typ == 8: vals.append(struct.unpack(endian+'h', chunk)[0])
        elif typ == 9: vals.append(struct.unpack(endian+'i', chunk)[0])
        elif typ == 5:
