    if data.startswith(b'BM'): return "image/bmp"
    if data[:4] in (b'II*\x00', b'MM\x00*'): return "image/tiff"
    if data.startswith(b'RIFF'):
        if data[8:12]==b'WEBP': return "image/webp"
        if data[8:12]==b'WAVE': return "audio/vnd.wave"
        return "application/x-riff"
    if data.startswith(b'%PDF'): return "application/pdf"
    if data[:4] in (b'PK\x03\x04', b'PK\x05\x06', b'PK\x07\x08'): return "application/zip"
    if data.startswith(b'\x1f\x8b'): return "application/gzip"
    if data.startswith(b'BZh'): return "application/x-bzip2"
    if data.startswith(b'\xfd7zXZ\x00'): return "application/x-xz"
    if data.startswith(b'7z\xbc\xaf\x27\x1c'): return "application/x-7z-compressed"
    if data.startswith(b'Rar!\x1a\x07'): return "application/vnd.rar"
    if data.startswith(b'ID3') or (len(data)>=2 and data[0]==0xFF and (data[1]&0xE0)==0xE0): return "audio/mpeg"
    if data.startswith(b'OggS'): return "audio/ogg"
    if data.startswith(b'fLaC'): return "audio/flac"
    if len(data)>=8 and data[4:8]==b'ftyp': return "video/mp4"
    stripped = data.lstrip()
    # strip BOM
    if stripped.startswith(b'\xef\xbb\xbf'): stripped=stripped[3:].lstrip()
    low = stripped.lower()
    if low.startswith(b'<?xml'):
        if b'<svg' in low[:2048]: return "image/svg+xml"
        return "application/xml"
    if low.startswith(b'<svg'): return "image/svg+xml"
    if low.startswith(b'<!doctype html') or low.startswith(b'<html'): return "text/html"
    # text detection
    if b'\x00' in data:
        return "application/octet-stream"
    try:
        data.decode('utf-8')
        # control chars other than tab/lf/cr/ff?
        for b in data:
            if b < 9 or (13 < b < 32):
                return "application/octet-stream"
        return "text/plain"
    except Exception:
        return "application/octet-stream"

