# ---------------- xattrs / acl / caps / extattrs ----------------
CAP_NAMES = ["cap_chown","cap_dac_override","cap_dac_read_search","cap_fowner","cap_fsetid","cap_kill","cap_setgid","cap_setuid","cap_setpcap","cap_linux_immutable","cap_net_bind_service","cap_net_broadcast","cap_net_admin","cap_net_raw","cap_ipc_lock","cap_ipc_owner","cap_sys_module","cap_sys_rawio","cap_sys_chroot","cap_sys_ptrace","cap_sys_pacct","cap_sys_admin","cap_sys_boot","cap_sys_nice","cap_sys_resource","cap_sys_time","cap_sys_tty_config","cap_mknod","cap_lease","cap_audit_write","cap_audit_control","cap_setfcap","cap_mac_override","cap_mac_admin","cap_syslog","cap_wake_alarm","cap_block_suspend","cap_perfmon","cap_bpf","cap_checkpoint_restore"]

def _list_xattrs(rec):
    if rec.archive is not None:
        return None
    try:
        return os.listxattr(rec.fs_path)  # follows symlinks like opening the file
    except Exception:
        return None
def _get_xattr(rec, name):
    if rec.archive is not None:
        return None
    try:
        return os.getxattr(rec.fs_path, name)
    except Exception:
        return None

def _parse_acl_xattr(data):
    if not data or len(data) < 4:
        return None
    version = struct.unpack_from('<I', data, 0)[0]
    entries = []
    off = 4
    while off+8 <= len(data):
        tag, perm, ident = struct.unpack_from('<HHI', data, off); off += 8
        entries.append((tag, perm, ident))
    return entries

def _acl_perm_str(perm):
    return ('r' if perm & 4 else '-')+('w' if perm & 2 else '-')+('x' if perm & 1 else '-')
def _acl_entries_str(entries):
    parts=[]
    for tag, perm, ident in entries:
        ps=_acl_perm_str(perm)
        if tag==0x01: parts.append(f"user::{ps}")
        elif tag==0x02:
            try: name=pwd.getpwuid(ident).pw_name
            except Exception: name=str(ident)
            parts.append(f"user:{name}:{ps}")
        elif tag==0x04: parts.append(f"group::{ps}")
        elif tag==0x08:
            try: name=grp.getgrgid(ident).gr_name
            except Exception: name=str(ident)
            parts.append(f"group:{name}:{ps}")
        elif tag==0x10: parts.append(f"mask::{ps}")
        elif tag==0x20: parts.append(f"other::{ps}")
        else: parts.append(f"{tag}:{ident}:{ps}")
    return ",".join(parts)

def _find_acl_entry(entries, spec):
    if entries is None or not spec:
        return None
    s=str(spec).strip()
    if ':' not in s:
        type_part=s; qual=''
    else:
        type_part, qual = s.split(':',1)
    type_part=type_part.lower()
    tagmap={'user':(0x01,0x02),'u':(0x01,0x02),'group':(0x04,0x08),'g':(0x04,0x08),'mask':(0x10,),'m':(0x10,),'other':(0x20,),'o':(0x20,)}
    tags=tagmap.get(type_part)
    if not tags: return None
    for tag,perm,ident in entries:
        if tag not in tags: continue
        if tag in (0x01,0x04):
            if qual=='' : return _acl_perm_str(perm)
            continue
        if tag in (0x10,0x20):
            if qual=='': return _acl_perm_str(perm)
            continue
        # named
        if qual=='' : continue
        # resolve qual as name or numeric
        name=None
        if tag==0x02:
            try: name=pwd.getpwuid(ident).pw_name
            except Exception: name=str(ident)
        else:
            try: name=grp.getgrgid(ident).gr_name
            except Exception: name=str(ident)
        if qual==name or qual==str(ident):
            return _acl_perm_str(perm)
    return None

EXTATTR_FLAGS = [
    (0x00000001,'s'),(0x00000002,'u'),(0x00000004,'c'),(0x00000008,'S'),(0x00000010,'i'),
    (0x00000020,'a'),(0x00000040,'d'),(0x00000080,'A'),(0x00010000,'E'),(0x00002000,'I'),
    (0x00004000,'j'),(0x00008000,'t'),(0x00040000,'D'),(0x00020000,'T'),(0x00080000,'e'),
    (0x00100000,'V'),(0x00200000,'C'),(0x00400000,'x'),(0x00800000,'N'),(0x01000000,'P'),(0x02000000,'F'),
]
def _extattrs(rec):
    """returns (letters string, has_bool_or_None)"""
    if rec.archive is not None:
        return ("", None)
    try:
        import fcntl, array
        # only attempt on regular file/dir to avoid blocking on fifo etc
        st = rec.lstat()
        if st is None: return ("", None)
        if not (stat.S_ISREG(st.st_mode) or stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode)):
            return ("", False)
        fd = os.open(rec.fs_path, os.O_RDONLY | getattr(os,'O_NONBLOCK',0))
        try:
            buf = array.array('l', [0])
            fcntl.ioctl(fd, 0x80086601, buf, True)
            flags = buf[0]
        finally:
            os.close(fd)
    except Exception:
        return ("", None)
    letters = ''.join(ch for bit,ch in EXTATTR_FLAGS if flags & bit)
    return (letters, bool(letters))

def _capabilities(rec):
    data = _get_xattr(rec, 'security.capability')
    if data is None:
        # distinguish file that can be listed vs broken: if xattr list fails, signal None
        if _list_xattrs(rec) is None:
            return None
        return set()
    caps=set()
    try:
        # struct is 20 bytes (v1) or 40? Use little endian u32 words: effective/permitted/inheritable pairs
        words = struct.unpack('<'+'I'*(len(data)//4), data[:len(data)//4*4])
        # words[0] magic, then permitted[0], inheritable[0], permitted[1], inheritable[1] in v2 kernel layout? 
        # kernel vfs_cap_data: magic_etc, permitted[2], inheritable[2]
        perm=[]
        if len(words)>=5:
            perm=[words[1], words[3]] if False else [words[1], words[2]]
            # actually layout after magic: permitted0, permitted1, inheritable0, inheritable1? vfs_cap_data order is permitted[2] then inheritable[2]
            perm=[words[1], words[2]]
        for idx in range(64):
            word = perm[idx//32] if idx//32 < len(perm) else 0
            if word & (1 << (idx%32)):
                if idx < len(CAP_NAMES): caps.add(CAP_NAMES[idx])
    except Exception:
        pass
    return caps

# ---------------- field values ----------------
def get_field(rec, canonical, ctx):
    cache = rec._cache
    if canonical in cache:
        return cache[canonical]
    val = _get_field_uncached(rec, canonical, ctx)
    cache[canonical] = val
    return val

def _get_field_uncached(rec, canonical, ctx):
    cfg = ctx.config
    if rec.archive is not None:
        return _archive_field(rec, canonical, ctx)
    st = rec.metadata()
    lst = rec.lstat()
    name = rec.name()
    rel = rec.rel_path
    if canonical == 'name':
        return name
    if canonical == 'filename':
        return split_filename(name)[0]
    if canonical == 'ext':
        return split_filename(name)[1]
    if canonical == 'path':
        return lossy(rel)
    if canonical == 'dir':
        return lossy(rel.rsplit('/',1)[0] if '/' in rel else '')
    if canonical == 'abspath':
        try:
            rp = os.path.realpath(rec.fs_path)
            if os.path.exists(rp) or os.path.lexists(rec.fs_path) and os.path.exists(rp):
                return lossy(rp)
            # canonicalise requires target existence
            if os.path.exists(rec.fs_path):
                return lossy(rp)
            return ""
        except Exception:
            return ""
    if canonical == 'absdir':
        try:
            parent = os.path.dirname(rec.fs_path) or '.'
            rp = os.path.realpath(parent)
            return lossy(rp) if rp else ""
        except Exception:
            return ""
    # metadata dependent
    def bool_str(b):
        return 'true' if b else 'false'
    if canonical == 'is_symlink':
        return bool_str(rec.is_symlink())
    if st is None:
        # many fields empty when metadata unavailable (broken symlink with follow)
        if canonical in ('size','fsize','uid','gid','user','group','created','accessed','modified','is_dir','is_file','is_pipe','is_char','is_block','is_socket','device','rdev','inode','blocks','hardlinks','atime','mtime','ctime','mode','user_read','user_write','user_exec','user_all','group_read','group_write','group_exec','group_all','other_read','other_write','other_exec','other_all','suid','sgid','is_sticky','is_empty','has_xattrs','xattr_count','extattrs','has_extattrs','acl','has_acl','default_acl','has_default_acl','has_capabilities','capabilities','width','height','duration','bitrate','freq','title','artist','album','mp3_year','genre','mime','line_count','is_binary','is_text','sha1','sha256','sha512','sha3'):
            return ""
        if canonical == 'is_hidden':
            return bool_str(name.startswith('.'))
        if canonical.startswith('is_') or canonical.startswith('has_'):
            # e.g. is_archive etc based on extension
            pass
        else:
            return ""
    if canonical == 'size':
        return str(st.st_size) if st else ""
    if canonical == 'fsize':
        if not st: return ""
        return format_size_value(st.st_size, cfg.default_file_size_format or "")
    if canonical == 'uid': return str(st.st_uid) if st else ""
    if canonical == 'gid': return str(st.st_gid) if st else ""
    if canonical == 'user':
        if not st: return ""
        try: return pwd.getpwuid(st.st_uid).pw_name
        except Exception: return ""
    if canonical == 'group':
        if not st: return ""
        try: return grp.getgrgid(st.st_gid).gr_name
        except Exception: return ""
    if canonical == 'created':
        if not st: return ""
        follow = bool(rec.root and rec.root.symlinks)
        bt = _statx_btime(rec.fs_path, follow)
        return format_local(bt) if bt else ""
    if canonical == 'accessed': return format_local(st.st_atime) if st else ""
    if canonical == 'modified': return format_local(st.st_mtime) if st else ""
    if canonical == 'atime': return str(int(st.st_atime)) if st else ""
    if canonical == 'mtime': return str(int(st.st_mtime)) if st else ""
    if canonical == 'ctime': return str(int(st.st_ctime)) if st else ""
    if canonical == 'device': return str(st.st_dev) if st else ""
    if canonical == 'rdev': return str(st.st_rdev) if st else ""
    if canonical == 'inode': return str(st.st_ino) if st else ""
    if canonical == 'blocks': return str(getattr(st,'st_blocks',0)) if st else ""
    if canonical == 'hardlinks': return str(st.st_nlink) if st else ""
    if canonical == 'mode':
        return mode_string(st.st_mode) if st else ""
    # permission booleans
    perm_map = {
        'user_read': stat.S_IRUSR,'user_write': stat.S_IWUSR,'user_exec': stat.S_IXUSR,
        'group_read': stat.S_IRGRP,'group_write': stat.S_IWGRP,'group_exec': stat.S_IXGRP,
        'other_read': stat.S_IROTH,'other_write': stat.S_IWOTH,'other_exec': stat.S_IXOTH,
    }
    if canonical in perm_map:
        return bool_str(bool(st and (st.st_mode & perm_map[canonical])))
    if canonical in ('user_all','group_all','other_all'):
        if not st: return ""
        mask = {'user_all':0o700,'group_all':0o070,'other_all':0o007}[canonical]
        return bool_str((st.st_mode & mask) == mask)
    if canonical == 'suid': return bool_str(bool(st and (st.st_mode & stat.S_ISUID)))
    if canonical == 'sgid': return bool_str(bool(st and (st.st_mode & stat.S_ISGID)))
    if canonical == 'is_sticky': return bool_str(bool(st and (st.st_mode & stat.S_ISVTX)))
    if canonical == 'is_dir': return bool_str(bool(st and stat.S_ISDIR(st.st_mode))) if st else ""
    if canonical == 'is_file': return bool_str(bool(st and stat.S_ISREG(st.st_mode))) if st else ""
    if canonical == 'is_pipe': return bool_str(bool(st and stat.S_ISFIFO(st.st_mode))) if st else ""
    if canonical == 'is_char': return bool_str(bool(st and stat.S_ISCHR(st.st_mode))) if st else ""
    if canonical == 'is_block': return bool_str(bool(st and stat.S_ISBLK(st.st_mode))) if st else ""
    if canonical == 'is_socket': return bool_str(bool(st and stat.S_ISSOCK(st.st_mode))) if st else ""
    if canonical == 'is_hidden':
        return bool_str(name.startswith('.'))
    if canonical == 'is_empty':
        if st is None: return ""
        if stat.S_ISDIR(st.st_mode):
            try:
                with os.scandir(rec.fs_path) as it:
                    for _ in it: return 'false'
                return 'true'
            except Exception:
                return 'false' if False else ""
        # non-dir: also treat symlink-to-dir via filesystem check
        try:
            if os.path.isdir(rec.fs_path) and not stat.S_ISDIR(st.st_mode):
                with os.scandir(rec.fs_path) as it:
                    for _ in it: return 'false'
                return 'true'
        except Exception:
            pass
