    if canonical in ('is_archive','is_audio','is_book','is_doc','is_font','is_image','is_source','is_video'):
        _, ext = split_filename(name)
        ext = ('.'+ext.lower()) if ext else ''
        lstmap = {'is_archive':cfg.is_archive,'is_audio':cfg.is_audio,'is_book':cfg.is_book,'is_doc':cfg.is_doc,'is_font':cfg.is_font,'is_image':cfg.is_image,'is_source':cfg.is_source,'is_video':cfg.is_video}
        return bool_str(ext in [e.lower() for e in lstmap[canonical]])
    if canonical == 'has_xattrs':
        xs = _list_xattrs(rec)
        if xs is None: return ""
        return bool_str(len(xs)>0)
    if canonical == 'xattr_count':
        xs = _list_xattrs(rec)
        if xs is None: return ""
        return str(len(xs))
    if canonical == 'extattrs':
        letters, has = _extattrs(rec)
        return letters
    if canonical == 'has_extattrs':
        letters, has = _extattrs(rec)
        if has is None: return ""
        return bool_str(has)
    if canonical in ('acl','has_acl','default_acl','has_default_acl'):
        is_default = canonical.startswith('default') or canonical.startswith('has_default')
        xname = 'system.posix_acl_default' if is_default else 'system.posix_acl_access'
        data = _get_xattr(rec, xname)
        if data is None:
            # if file cannot be opened / xattr unsupported, original returns empty for these
            return ""
        entries = _parse_acl_xattr(data)
        if canonical in ('acl','default_acl'):
            return _acl_entries_str(entries) if entries else ""
        # has_*
        if not entries: return ""
        if is_default:
            return bool_str(len(entries)>0)
        extended = any(tag in (0x02,0x08,0x10) for tag,_,_ in entries)
        return bool_str(extended)
    if canonical == 'has_capabilities':
        caps = _capabilities(rec)
        if caps is None: return ""
        return bool_str(len(caps)>0)
    if canonical == 'capabilities':
        caps = _capabilities(rec)
        if not caps: return ""
        # ordering by capability id
        ordered = [c for c in CAP_NAMES if c in caps]
        return ",".join(ordered)
    if canonical in ('width','height'):
        # only for image-like extensions or mp4
        _, ext = split_filename(name)
        extd = ('.'+ext.lower()) if ext else ''
        if extd not in [e.lower() for e in cfg.is_image] and extd not in ('.mp4','.mov','.m4v'):
            return ""
        w,h = parse_image_dimensions(rec)
        v = w if canonical=='width' else h
        return str(v) if v is not None else ""
    if canonical in ('duration','bitrate','freq','title','artist','album','mp3_year','genre'):
        _, ext = split_filename(name)
        if ext.lower() != 'mp3':
            return ""
        info = parse_mp3(rec)
        if canonical=='duration': return str(info['duration']) if info['duration'] is not None else ""
        if canonical=='bitrate': return str(info['bitrate']) if info['bitrate'] is not None else ""
        if canonical=='freq': return str(info['freq']) if info['freq'] is not None else ""
        return str(info[canonical])
    if canonical.startswith('exif_'):
        # gate roughly to image files with exif data; parse_exif returns {} for others
        return _exif_format_value(rec, canonical)
    if canonical == 'mime':
        return _mime_of(rec, ctx)
    if canonical == 'line_count':
        data = rec.content_bytes()
        if data is None: return ""
        return str(data.count(b'\n'))
    if canonical in ('is_binary','is_text'):
        if st and stat.S_ISDIR(st.st_mode):
            return 'false'
        mime = _mime_of(rec, ctx)
        if not mime:
            return 'false'
        is_text = mime.startswith('text/')
        return bool_str(is_text) if canonical=='is_text' else bool_str(not is_text)
    if canonical in ('sha1','sha256','sha512','sha3'):
        data_hash = None
        # only regular files (following)
        try:
            if not os.path.isfile(rec.fs_path):
                return ""
        except Exception:
            return ""
        hname = {'sha1':'sha1','sha256':'sha256','sha512':'sha512','sha3':'sha3_512'}[canonical]
        try:
            h = hashlib.new(hname)
            with open(rec.fs_path,'rb') as f:
                while True:
                    chunk=f.read(65536)
                    if not chunk: break
                    h.update(chunk)
            return h.hexdigest()
        except Exception:
            return ""
    return ""

def _archive_field(rec, canonical, ctx):
    cfg = ctx.config
    info = rec.archive['info']
    rel = rec.rel_path
    name = rec.name()
    if canonical == 'name': return name
    if canonical == 'filename': return split_filename(name)[0]
    if canonical == 'ext': return split_filename(name)[1]
    if canonical == 'path': return lossy(rel)
    if canonical == 'abspath': return lossy(rel)
    if canonical == 'dir': return lossy(rel.rstrip('/').rsplit('/',1)[0] if '/' in rel.rstrip('/') else '')
    if canonical == 'absdir': return lossy(rel.rstrip('/').rsplit('/',1)[0] if '/' in rel.rstrip('/') else '')
    if canonical == 'size': return str(info.file_size)
    if canonical == 'fsize': return format_size_value(info.file_size, cfg.default_file_size_format or "")
    if canonical == 'modified':
        try:
            dt = datetime.datetime(*info.date_time)
            return dt.strftime("%Y-%m-%d %H:%M:%S")
        except Exception:
            return ""
    if canonical == 'mode':
        modebits = (info.external_attr >> 16) & 0xFFFF
        if modebits == 0:
            modebits = 0o40755 if info.is_dir() else 0o100600
        elif not (modebits & 0o170000):
            modebits |= 0o040000 if info.is_dir() else 0o100000
        return mode_string(modebits)
    if canonical == 'is_dir': return 'true' if info.is_dir() else 'false'
    if canonical == 'is_file': return 'false' if info.is_dir() else 'true'
    if canonical == 'is_symlink': return 'false'
    if canonical == 'is_hidden': return 'true' if name.startswith('.') else 'false'
    if canonical == 'is_empty':
        if info.is_dir(): return 'true'
        return 'true' if info.file_size==0 else 'false'
    if canonical in ('is_archive','is_audio','is_book','is_doc','is_font','is_image','is_source','is_video'):
        _, ext = split_filename(name); ext = ('.'+ext.lower()) if ext else ''
        lstmap = {'is_archive':cfg.is_archive,'is_audio':cfg.is_audio,'is_book':cfg.is_book,'is_doc':cfg.is_doc,'is_font':cfg.is_font,'is_image':cfg.is_image,'is_source':cfg.is_source,'is_video':cfg.is_video}
        return 'true' if ext in [e.lower() for e in lstmap[canonical]] else 'false'
    # most other fields empty for archive entries
    return ""

def _mime_of(rec, ctx):
    if rec.archive is not None:
        return ""
    # directory check (metadata)
    st = rec.metadata()
    lst = rec.lstat()
    # if target is directory via path (covers symlinks)
    try:
        if os.path.isdir(rec.fs_path):
            # regular dirs and symlink-to-dir both report inode/directory
            # but ensure the path exists
            if os.path.exists(rec.fs_path):
                return "inode/directory"
    except Exception:
        pass
    if st is not None and stat.S_ISDIR(st.st_mode):
        return "inode/directory"
    data = rec.content_preview(8192)
    if data is None:
        return ""
    if len(data)==0:
        return "text/plain"
    # magic
    if data.startswith(b'\x89PNG\r\n\x1a\n'): return "image/png"
    if data.startswith(b'\xff\xd8\xff'): return "image/jpeg"
    if data[:6] in (b'GIF87a',b'GIF89a'): return "image/gif"
    if data.startswith(b'BM'): return "image/bmp"
    if data[:4] in (b'II*\x00', b'MM\x00*'): return "image/tiff"
    if data.startswith(b'RIFF'):
        if data[8:12]==b'WEBP': return "image/webp"
        if data[8:12]==b'WAVE': return "audio/vnd.wave"
        return "application/x-riff"
    if data.startswith(b'%PDF'): return "application/pdf"
    if data[:4] in (b'PK\x03\x04', b'PK\x05\x06', b'PK\x07\x08'): return "application/zip"
    if data.startswith(b'\x1f\x8b'): return "application/gzip"
    if data.startswith(b'BZh'): return "application/x-bzip2"
    if data.startswith(b'\xfd7zXZ\x00'): return "application/x-xz"
    if data.startswith(b'7z\xbc\xaf\x27\x1c'): return "application/x-7z-compressed"
