    if entries is None or not spec:
        return None
    s=str(spec).strip()
    if ':' not in s:
        type_part=s; qual=''
    else:
        type_part, qual = s.split(':',1)
    type_part=type_part.lower()
    tagmap={'user':(0x01,0x02),'u':(0x01,0x02),'group':(0x04,0x08),'g':(0x04,0x08),'mask':(0x10,),'m':(0x10,),'other':(0x20,),'o':(0x20,)}
    tags=tagmap.get(type_part)
    if not tags: return None
    for tag,perm,ident in entries:
        if tag not in tags: continue
        if tag in (0x01,0x04):
            if qual=='' : return _acl_perm_str(perm)
            continue
        if tag in (0x10,0x20):
            if qual=='': return _acl_perm_str(perm)
