# ---------------- execution context ----------------
class ExecCtx:
    def __init__(self, config, color_enabled, show_errors, us_dates_flag):
        self.config = config
        self.color_enabled = color_enabled
        self.show_errors = show_errors
        self.us_dates = config.us_dates or us_dates_flag
        self.exit_code = 0
        self.where_div_sticky = False
    def report(self, prefix, msg):
        if self.show_errors:
            p = f"\x1b[33m{prefix}\x1b[0m" if self.color_enabled else prefix
            try:
                sys.stderr.write(f"{p}: {msg}\n")
            except Exception:
                pass
    def report_eval(self, rec, err):
        if err.prefix == 'expression':
            self.report('expression', err.msg)
        elif err.prefix == 'query':
            self.report('query', err.msg)
        elif err.prefix == 'query-invalid':
            self.report('query', err.msg)
        else:
            self.report(rec.error_path if rec else 'query', err.msg)

# ---------------- expression evaluation ----------------
def eval_expr(e, rec, ctx, env, agg_records=None):
    if isinstance(e, LiteralExpr):
        return e.text
    if isinstance(e, FieldExpr):
        if agg_records is not None:
            return ""
        if rec is None:
            return ""
        return get_field(rec, e.canonical, ctx)
    if isinstance(e, AliasFieldExpr):
        if agg_records is not None:
            return ""
        if rec is not None and rec.root is not None and rec.root.alias and rec.root.alias.lower() == e.alias.lower():
            return get_field(rec, e.canonical, ctx)
        bound = env.get(e.alias.lower()) if env else None
        if bound is not None:
            return get_field(bound, e.canonical, ctx)
        if rec is None:
            return ""
        return get_field(rec, e.canonical, ctx)
    if isinstance(e, StarExpr):
        return "*"
    if isinstance(e, GroupExpr):
        return eval_expr(e.inner, rec, ctx, env, agg_records)
    if isinstance(e, NegExpr):
        # quirk: -field evaluates as field value
        return eval_expr(e.inner, rec, ctx, env, agg_records)
    if isinstance(e, ArithExpr):
        lv = eval_expr(e.left, rec, ctx, env, agg_records)
        rv = eval_expr(e.right, rec, ctx, env, agg_records)
        return arith_op(lv, e.op, rv)
    if isinstance(e, FuncExpr):
        if e.canonical in AGG_FUNCS:
            if agg_records is not None:
                return compute_aggregate(e, agg_records, rec, ctx, env)
            else:
                # singleton aggregate in non-aggregate context
                if rec is None:
                    return "1" if e.canonical=='count' else ""
                return compute_aggregate(e, [rec], rec, ctx, env)
        # evaluate args (aggregates inside non-agg funcs handled recursively)
        vals = [eval_expr(a, rec, ctx, env, agg_records) for a in e.args]
        return eval_function(e.canonical, vals, e.args, rec, ctx, env)
    return ""

def arith_op(lv, op, rv):
    # division / modulo by zero check
    rn = parse_number_loose(rv)
    if op in ('/','%') and rn == 0:
        raise EvalError("Division by zero", 'file')
    # integer arithmetic if both integer-like
    if op != '/' and is_integer_string(lv) and is_integer_string(rv):
        a = int(str(lv).strip()); b = int(str(rv).strip())
        if op == '+': r = a+b
        elif op == '-': r = a-b
        elif op == '*': r = a*b
        elif op == '%':
            # rust style remainder (sign of dividend)
            r = int(math.fmod(a, b))
        else: r = 0
        # wrap to i64 like release-mode Rust
        if r > 9223372036854775807 or r < -9223372036854775808:
            r = ((r + 2**63) % 2**64) - 2**63
        return str(r)
    a = parse_number_loose(lv); b = rn
    if op == '+': x=a+b
    elif op == '-': x=a-b
    elif op == '*': x=a*b
    elif op == '/': x=a/b
    elif op == '%': x=math.fmod(a,b)
    else: x=0
    return rust_float_str(x)

