def _ignore_glob_to_regex(pat, anchored):
    # translate git wildmatch; returns regex that search()s
    i=0; out=[]
    # we will build full-match pattern for either whole string or basename variants using search with (?:^|.*/)
    while i < len(pat):
        c=pat[i]
        if c=='*':
            if i+1 < len(pat) and pat[i+1]=='*':
                # **/
                if i+2 < len(pat) and pat[i+2]=='/':
                    out.append('(?:.*/)?'); i+=3; continue
                else:
                    out.append('.*'); i+=2; continue
            out.append('[^/]*'); i+=1; continue
        if c=='?': out.append('[^/]'); i+=1; continue
        if c=='[':
            j=i+1
            if j < len(pat) and pat[j] in ('!','^'): j+=1
            if j < len(pat) and pat[j]==']': j+=1
            while j < len(pat) and pat[j]!=']': j+=1
            if j>=len(pat):
                out.append(re.escape(c)); i+=1; continue
            stuff=pat[i+1:j]
            if stuff.startswith('!'): stuff='^'+stuff[1:]
            out.append('['+stuff+']'); i=j+1; continue
        out.append(re.escape(c)); i+=1
    core=''.join(out)
    if anchored:
        return '^'+core+'$'
    else:
        return '(?:^|.*/)'+core+'$' if '/' not in pat else '^'+core+'$'

def parse_ignore_file(path, base_prefix):
    rules=[]
    try:
        with open(path,'r',encoding='utf-8',errors='replace') as f: lines=f.read().splitlines()
    except Exception:
        return rules
    for line in lines:
        s=line
        if s.endswith('\r'): s=s[:-1]
        # trailing spaces are stripped unless escaped (simplify)
        s=s.rstrip(' ')
        if not s: continue
        if s.startswith('#'): continue
        neg=False
        if s.startswith('!'): neg=True; s=s[1:]
        elif s.startswith('\\!'): s=s[1:]
        elif s.startswith('\\#'): s=s[1:]
        if not s: continue
        dir_only=s.endswith('/')
        if dir_only: s=s.rstrip('/')
        anchored=False
        if '/' in s:
            anchored=True
            s=s.lstrip('/')
        rules.append(IgnoreRule(base_prefix, s, neg, dir_only, anchored))
    return rules

def _is_git_repo_dir(d):
    gd=os.path.join(d,'.git')
    if os.path.isfile(gd):
        try:
            txt=open(gd).read().strip()
            if txt.startswith('gitdir:'):
                gd=txt.split(':',1)[1].strip()
                if not os.path.isabs(gd): gd=os.path.join(d,gd)
            else: return False
        except Exception: return False
    if not os.path.isdir(gd): return False
    head=os.path.join(gd,'HEAD')
    try:
        if not os.path.isfile(head) or not open(head).read().strip(): return False
    except Exception: return False
    return os.path.isdir(os.path.join(gd,'objects')) and os.path.isdir(os.path.join(gd,'refs'))

def _find_up(start, names):
    d=os.path.abspath(start)
    while True:
        for nm in names:
            if os.path.exists(os.path.join(d,nm)):
                return d
        parent=os.path.dirname(d)
        if parent==d: return None
        d=parent

