def _glob_regex(pattern):
    out=[]
    for ch in pattern:
        if ch=='*': out.append('.*')
        elif ch=='?': out.append('.')
        else: out.append(re.escape(ch))
    return '^'+''.join(out)+'$'
def _like_regex(pattern):
    out=[]
    for ch in pattern:
        if ch=='%': out.append('.*')
        elif ch=='_': out.append('.')
        else: out.append(re.escape(ch))
    return '^'+''.join(out)+'$'

def _date_interval(rv, ctx):
    p=parse_date_value(rv, ctx.us_dates)
    if p is None:
        raise EvalError(f"Can't parse datetime: {rv}", 'file')
    start, interval = p
    end = start + datetime.timedelta(seconds=interval-1)
    return start,end
