def eval_condition(cond, rec, ctx, env, query):
    if isinstance(cond, AndCond):
        return eval_condition(cond.l, rec, ctx, env, query) and eval_condition(cond.r, rec, ctx, env, query)
    if isinstance(cond, OrCond):
        return eval_condition(cond.l, rec, ctx, env, query) or eval_condition(cond.r, rec, ctx, env, query)
    if isinstance(cond, NotCond):
        return not eval_condition(cond.c, rec, ctx, env, query)
    if isinstance(cond, LeafCond):
        if expr_type(cond.e) != 'bool':
            return False
        v=eval_expr(cond.e, rec, ctx, env)
        return parse_bool(v)
    if isinstance(cond, ExistsCond):
        rows = execute_subquery(cond.subquery, rec, ctx, env, 'exists')
        result = len(rows)>0
        return (not result) if cond.negated else result
    if isinstance(cond, CompareCond):
        return eval_compare(cond, rec, ctx, env, query)
    return False

