def _process_node_bfs(node, state, q, ctx, alias_env, records):
    entries=_list_node(node, state, ctx)
    if entries is None: return []
    expansions=[]
    for entry in entries:
        name=lossy(entry.name)
        # use raw entry name for fs path via stored prefix joining (entry path from scandir is reliable)
        fs_path=entry.path
        stored=_join_disp(node.stored_prefix, entry.name)
        # if node stored prefix is a filesystem path equal to node.fs_path, entry.path may differ in // etc; keep stored as built
