def _process_node_dfs(node, state, q, ctx, alias_env, records):
    entries=_list_node(node, state, ctx)
    if entries is None: return
    for entry in entries:
        stored=_join_disp(node.stored_prefix, entry.name)
        rel=_join_rel(node.rel_prefix, entry.name)
        rec=FileRecord(entry.path, stored, rel, state.root, node.depth+1)
        if _record_ignored(state, rec, state.canonical_root):
            continue
        can=_visit_record(rec, q, ctx, alias_env, records, state)
        _expand_archive(rec, q, ctx, alias_env, records, state)
        exp=_dir_expansion(rec, state, can)
        if exp is not None:
            _process_node_dfs(exp, state, q, ctx, alias_env, records)

