class DirNode:
    __slots__=('fs_path','stored_prefix','rel_prefix','depth')
    def __init__(self, fs_path, stored_prefix, rel_prefix, depth):
        self.fs_path=fs_path; self.stored_prefix=stored_prefix; self.rel_prefix=rel_prefix; self.depth=depth

class Row:
    __slots__=('cells','cell_map','rec','records','group_keys','archive_prefix','field_count')
    def __init__(self, cells=None, rec=None, records=None):
        self.cells=cells or []; self.cell_map={}; self.rec=rec; self.records=records or ([rec] if rec else []); self.group_keys={}; self.archive_prefix=None
        if rec is not None:
            self.archive_prefix=rec.archive_prefix

def _join_disp(prefix, name):
    if prefix == '':
        return name
    if prefix.endswith('/'):
        return prefix+name
    return prefix+'/'+name
def _join_rel(prefix, name):
    if prefix == '':
        return name
    if prefix.endswith('/'):
        return prefix+name
    return prefix+'/'+name

def _clone_root(root, path):
    r=Root(path)
    r.__dict__.update(root.__dict__)
    r.path=path
    return r

def expand_regex_roots(root):
    pat=root.path
    if not root.regexp or ('*' not in pat and '[' not in pat):
        return [root]
    if pat.startswith('/'):
        cur=['/']; comps=[c for c in pat[1:].split('/')]
    else:
        cur=['']; comps=pat.split('/')
    for comp in comps:
        new=[]
        if '*' in comp or '[' in comp:
            regex_str=comp
            if regex_str.startswith('*'):
                regex_str='.*'+regex_str[1:]
            try:
                rx=re.compile('^'+regex_str+'$')
            except Exception:
                rx=None
            for base in cur:
                listdir = base if base else '.'
                try:
                    entries=list(os.scandir(listdir))
                except Exception:
                    continue
                for entry in entries:
                    if rx and rx.search(entry.name):
                        new.append(_join_disp(base, entry.name) if base!='/' else '/'+entry.name)
                        if base=='/':
                            new[-1]='/'+entry.name
            cur=new
        else:
            for base in cur:
                if base=='/': new.append('/'+comp)
                elif base=='': new.append(comp)
                else: new.append(base+'/'+comp)
            cur=new
        if not cur:
            break
    return [_clone_root(root, c) for c in cur]

