def execute_subquery(node, current_rec, ctx, env, op_kind):
    if node.invalid_alias is not None:
        raise EvalError(f"Invalid root alias: {node.invalid_alias}", 'query-invalid')
    # parse fresh (deferred alias errors repeat per file)
    try:
        subq = parse_query(node.tokens, ctx.config, outer_aliases=node.outer_aliases, is_subquery=True)
    except InvalidAliasError as e:
        raise EvalError(f"Invalid root alias: {e.alias}", 'query-invalid')
