    outer_refs=[]
    seen=set()
    for r in refs:
        if r.alias.lower() in [a.lower() for a in node.outer_aliases] and (subq.primary_alias is None or r.alias.lower()!=subq.primary_alias.lower()):
            k=(r.alias.lower(), r.canonical)
