                raise EvalError(f"Invalid root alias: {v.split('.',1)[0]}", 'query-invalid')
    if not correlated and node._cached_done:
        return node._cached_result
    saved_exit=ctx.exit_code
    sub_env=dict(env)
    # bind outer alias(es) explicitly to current record where they refer to the enclosing query's records
    for r in outer_refs:
        if r.alias.lower() not in sub_env:
            sub_env[r.alias.lower()]=current_rec
    rows = execute_query_rows(subq, ctx, sub_env, is_subquery=True)
    # subquery errors are reported but do not change the outer exit code
    ctx.exit_code=saved_exit
