    ctx.where_div_sticky=False
    records=[]
    for root in q.roots:
        for eroot in expand_regex_roots(root):
            _traverse_root(eroot, q, ctx, alias_env, records)
    # build rows
    agg_mode = any(expr_contains_agg(c) for c in q.fields)
    rows=[]
    if agg_mode:
        rows=_build_agg_rows(q, records, ctx, alias_env)
    else:
        # static?
        static = all(not expr_contains_field(c) for c in q.fields)
        if static:
            if records:
                rec=records[0]
                try:
                    cells=[]
                    for idx,col in enumerate(q.fields):
                        cells.append(eval_expr(col, rec, ctx, alias_env))
                    row=Row(cells, rec); row.cell_map={i:v for i,v in enumerate(cells)}; row.archive_prefix=None
                    rows=[row]
                except EvalError as err:
                    ctx.report_eval(rec, err)
                    if err.prefix!='query-invalid': ctx.exit_code=1
                    rows=[]
        else:
            for rec in records:
                try:
                    cells=[]
                    for col in q.fields:
                        cells.append(eval_expr(col, rec, ctx, alias_env))
                    row=Row(cells, rec); row.cell_map={i:v for i,v in enumerate(cells)}; rows.append(row)
                except EvalError as err:
                    ctx.report_eval(rec, err)
                    if err.prefix!='query-invalid': ctx.exit_code=1
