            except EvalError as err:
                ctx.report_eval(rec, err)
                if err.prefix!='query-invalid': ctx.exit_code=1
                continue
            if key not in groups:
                groups[key]=[]; order.append(key)
            groups[key].append(rec)
    else:
        groups={(): list(records)}; order=[()]
    rows=[]
    for key in order:
        grecs=groups[key]
        rep=grecs[0] if grecs else None
        row=Row([], rep, grecs)
        row.group_keys={norm_expr_key(g): v for g,v in zip(q.group_by, key)}
        cells=[]; cmap={}
        for idx,col in enumerate(q.fields):
