def _sort_rows(q, rows, ctx, alias_env, agg_mode):
    from functools import cmp_to_key
    # precompute keys
    keyed=[]
    for row in rows:
        keys=[]
        for spec in q.order_by:
            if spec.positional is not None:
                val=row.cell_map.get(spec.positional, "")
                etype=expr_type(q.fields[spec.positional])
            else:
                nk=norm_expr_key(spec.expr)
                if agg_mode and nk in row.group_keys:
                    val=row.group_keys[nk]; etype=expr_type(spec.expr)
                elif agg_mode:
                    try: val=eval_expr(spec.expr, row.rec, ctx, alias_env, agg_records=row.records)
                    except EvalError as err:
                        if row.rec: ctx.report_eval(row.rec, err)
                        if err.prefix!='query-invalid': ctx.exit_code=1
                        val=""
                    etype=expr_type(spec.expr)
                else:
                    if expr_contains_agg(spec.expr):
