# ---------------- interactive ----------------
def run_interactive(config, color_enabled, show_errors, us_flag, ctx_config):
    ctx=ExecCtx(config, color_enabled, show_errors, us_flag)
    # history setup
    hist_path=None
    std=standard_config_path()
    old_entries=[]; session_entries=[]
    if std:
        hist_path=os.path.join(os.path.dirname(std),'history.txt')
        try:
            if os.path.exists(hist_path):
                with open(hist_path,'r',encoding='utf-8',errors='replace') as f:
                    lines=f.read().splitlines()
                if lines and lines[0]=='#V2': lines=lines[1:]
                old_entries=lines
        except Exception: pass
    # readline if tty
    is_tty=False
    try: is_tty=sys.stdin.isatty()
    except Exception: pass
    rl=None
    if is_tty:
        try:
            import readline as rl_mod; rl=rl_mod
            for e in old_entries:
                try: rl.add_history(e)
                except Exception: pass
        except Exception: rl=None
    errors_on=show_errors
    def save_history():
        if not hist_path: return
        try:
            os.makedirs(os.path.dirname(hist_path), exist_ok=True)
            # write with 0600 if new
            fd=os.open(hist_path, os.O_WRONLY|os.O_CREAT|os.O_TRUNC, 0o600)
            with os.fdopen(fd,'w',encoding='utf-8') as f:
                f.write('#V2\n')
                for e in old_entries+session_entries:
                    f.write(e.replace('\\','\\')+'\n')
        except Exception: pass
    while True:
        try:
            if is_tty:
                line=input('query> ')
            else:
                # no prompt
                raw=sys.stdin.readline()
                if raw=='':
                    raise EOFError()
                line=raw.rstrip('\n')
                if line.endswith('\r'): line=line[:-1]
        except EOFError:
            try: sys.stdout.write('CTRL-D\n'); sys.stdout.flush()
            except Exception: pass
            break
        except KeyboardInterrupt:
            break
        trimmed=line.strip()
        low=trimmed.lower()
        is_builtin_history_skip = low in ('pwd','help','exit','quit')
        if not is_builtin_history_skip:
            session_entries.append(line)
            if rl:
                try: rl.add_history(line)
                except Exception: pass
        if low in ('exit','quit'):
            break
        if low=='help':
            _write_help(full_help(color_enabled)); continue
        if low=='pwd':
            try: sys.stdout.write(os.getcwd()+'\n'); sys.stdout.flush()
            except Exception: pass
            continue
        # errors command: 'errors' or 'errors' + spaces + on/off (space-separated only)
        if low=='errors' or (low.startswith('errors') and len(low)>6 and low[6]==' '):
            rest=low[6:].strip() if len(low)>6 else ''
            # rest must be exactly on/off after collapsing spaces (tabs were treated as query)
            if ' ' in line.strip() or '\t' not in line:
                if rest=='on': errors_on=True
                elif rest=='off': errors_on=False
            state='ON' if errors_on else 'OFF'
            disp=f"\x1b[33m{state}\x1b[0m" if color_enabled else state
            try: sys.stdout.write(f"Errors are {disp}\n"); sys.stdout.flush()
            except Exception: pass
            continue
        if low.startswith('cd') and len(trimmed)>=3 and trimmed[2]==' ':
            # case-insensitive cd already in low; use actual trimmed
            path=trimmed[3:].strip() if len(trimmed)>3 else ''
            if not path:
                if errors_on: ctx.report('cd','no path specified')
                continue
            try:
                os.chdir(path)
            except OSError as e:
                if errors_on:
                    msg=os.strerror(e.errno) if e.errno else str(e)
                    ctx.report('cd', f"{msg} (os error {e.errno})")
            continue
        if low=='cd':
            if errors_on: ctx.report('cd','no path specified')
            continue
        # run query
        ctx.show_errors=errors_on
        # each query uses a fresh exit/sticky but same ctx settings
        ctx.exit_code=0
        ctx.where_div_sticky=False
        run_query_text(line, ctx)
    save_history()
    return 0

def is_interactive_arg(a):
    low=a.lower()
    return low.startswith('-i') or low.startswith('/i') or low.startswith('--i')

# ---------------- main ----------------
def main(argv):
    args=argv[1:]
    config, initial_exists, _std = initial_config()
    color_enabled = ('NO_COLOR' not in os.environ) and (not config.no_color)
    if not args:
        _write_help(short_help(color_enabled, extra=True))
        return 0
    first=args[0]; low_first=first.lower()
    # version takes precedence over help (observed)
    if 'version' in low_first or low_first.startswith('-v'):
        _write_help(short_help(color_enabled, extra=False))
        return 0
    if 'help' in low_first or low_first.startswith('-h') or low_first.startswith('/h') or low_first.startswith('/?'):
        _write_help(full_help(color_enabled))
        return 0
    if is_interactive_arg(first):
        ensure_config_created(initial_exists, False, False)
        return run_interactive(config, color_enabled, True, False, config)
    # flag loop over leading arguments
    show_errors=True; us_flag=False; flag_no_color=False
    custom_seen=False; custom_failed=False
    interactive=False
    idx=0
    while idx < len(args):
        arg=args[idx]; low=arg.lower()
        if 'nocolor' in low or 'no-color' in low:
            flag_no_color=True; idx+=1; continue
        if low.startswith('--no-errors'):
            show_errors=False; idx+=1; continue
        if low.startswith('--us-dates'):
            us_flag=True; idx+=1; continue
        if low.startswith('-c') or low.startswith('/c') or low.startswith('--config'):
            if idx+1>=len(args):
                try: sys.stderr.write('Error: --config requires a path argument\n')
                except Exception: pass
                return 2
            cfgpath=args[idx+1]
            cfg, ok = read_config_file(cfgpath, print_errors=True)
            config=cfg; custom_seen=True; custom_failed=not ok
            idx+=2; continue
        if is_interactive_arg(arg):
            interactive=True; idx+=1; break
        break
    if flag_no_color:
        color_enabled=False
    if interactive:
        ensure_config_created(initial_exists, custom_seen, custom_failed)
        return run_interactive(config, color_enabled, show_errors, us_flag, config)
    remaining=args[idx:]
    if not remaining:
        _write_help(short_help(color_enabled, extra=True))
        return 0
    ensure_config_created(initial_exists, custom_seen, custom_failed)
    ctx=ExecCtx(config, color_enabled, show_errors, us_flag)
    query_text=' '.join(remaining)
    return run_query_text(query_text, ctx)

if __name__=='__main__':
    try:
        sys.exit(main(sys.argv))
    except BrokenPipeError:
        os._exit(0)

