# ---------------- output ----------------
def _color_for_record(rec, ctx):
    if rec is None or rec.archive is not None:
        return None
    st=rec.metadata()
    if st is None:
        if rec.is_symlink(): return '1;36'
        return None
    m=st.st_mode
    if stat.S_ISDIR(m): return '1;34'
    if stat.S_ISLNK(m): return '1;36'
    if stat.S_ISSOCK(m): return '1;35'
    if stat.S_ISFIFO(m): return '33'
    if stat.S_ISCHR(m) or stat.S_ISBLK(m): return '1;33'
    if stat.S_ISREG(m) and (m & 0o111): return '1;32'
    return None

def format_rows(q, rows, ctx, query_text):
    fmt=q.fmt
    field_count=len(q.fields)
    agg_mode = any(expr_contains_agg(c) for c in q.fields)
    if fmt=='json':
        objs=[]
        for row in rows:
            d={}
            for idx,col in enumerate(q.fields):
                if idx not in row.cell_map: continue
                key=expr_agg_key(col) if agg_mode else expr_display(col)
                d[key]=row.cell_map[idx]
            if row.archive_prefix:
                d['archive']=row.archive_prefix
            objs.append(dict(sorted(d.items())))
        return json.dumps(objs, ensure_ascii=False, separators=(',',':'))+"\n"
    if fmt=='html':
        def esc(s):
            return s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;')
        parts=[f'<html><head><title>{query_text}</title></head><body><table><tr><th colspan="{field_count}">{query_text}</th></tr>']
        for row in rows:
            cells=[]
            if row.archive_prefix: cells.append(row.archive_prefix)
            cells.extend(row.cells)
            parts.append('<tr>'+''.join(f'<td>{esc(c)}</td>' for c in cells)+'</tr>')
        parts.append('</table></body></html>')
        return ''.join(parts)+"\n"
    # text formats (tabs/lines/list/csv)
    use_color = ctx.color_enabled and sys.stdout.isatty() and fmt in ('tabs','lines')
    def colored_cells(row):
        cells=list(row.cells)
        if not use_color:
            return cells
        code=_color_for_record(row.rec, ctx)
        if not code:
            return cells
        # colour cells whose field is name
        for idx,col in enumerate(q.fields):
            if idx>=len(cells): break
            is_name=False
            if isinstance(col, FieldExpr) and col.canonical=='name': is_name=True
            if isinstance(col, AliasFieldExpr) and col.canonical=='name': is_name=True
            if is_name:
                cells[idx]=f"\x1b[{code}m{cells[idx]}\x1b[0m"
        return cells
    if fmt=='csv':
        buf=io.StringIO()
        w=csv.writer(buf, lineterminator='\n')
        for row in rows:
            cells=[]
            if row.archive_prefix: cells.append(row.archive_prefix)
            cells.extend(row.cells)
            w.writerow(cells)
        return buf.getvalue()
    out=[]
    for row in rows:
        cells=[]
        if row.archive_prefix: cells.append(row.archive_prefix)
        cells.extend(colored_cells(row))
        if fmt=='lines':
            for c in cells: out.append(c+"\n")
        elif fmt=='list':
            for c in cells: out.append(c+"\x00")
        else:
            out.append("\t".join(cells)+"\n")
    return ''.join(out)

